package locale

func init() {
	Register("[Member nodes to compact]:\n", "[Member nodes to compact]:\n", "[압축할 구성원 노드]:\n")
	Register("- #%d produces/derives -> #%d", "- #%d produces/derives -> #%d", "- #%d 산출/파생 -> #%d")
	Register("\n[Lineage edges between members (parent -> child)]:\n", "\n[Lineage edges between members (parent -> child)]:\n", "\n[구성원 간 계보 연결(부모 -> 자식)]:\n")
	Register("\n[Common parent/context anchor: not a member; identifies the intent that produced these results]:\n", "\n[Common parent/context anchor: not a member; identifies the intent that produced these results]:\n", "\n[공통 부모/문맥 연결점: 구성원이 아니며 이 결과를 만든 의도를 이해하기 위한 정보]:\n")
	Register("Compact a group of RELATED exploration nodes into an integrated conclusion (body) so the planner can quickly understand what this area has established.\nInput is a connected subgraph:\n- Nodes: one-sentence intent/fact summaries with id, type, state, and confidence when present.\n- Relationships: lineage edges showing how one node derives from or produces another.\n- If nodes lack direct edges but share an upstream intent supplied as common parent #p, synthesize what that intent discovered. The common parent is context, not a member to compact.\nWrite the body as follows:\n1. Synthesize rather than enumerate. Follow causal relationships: which fact motivated an intent and which intent produced a conclusion. Do not copy every summary.\n2. Preserve distinctions between different conclusions instead of merging them into a vague sentence.\n3. Preserve evidence strength with observed/inferred labels. Inferred negative/uncertain conclusions remain tentative and open to verification, never definitive.\n4. Cite source node IDs after each conclusion, such as (#12,#28), so the planner can retrieve originals.\n5. State only what the input supports; introduce no invented information or judgments.\n6. Adapt length to the number of distinct conclusions, while remaining substantially shorter than all input summaries combined.\nOutput only the body.", "Compact a group of RELATED exploration nodes into an integrated conclusion (body) so the planner can quickly understand what this area has established.\nInput is a connected subgraph:\n- Nodes: one-sentence intent/fact summaries with id, type, state, and confidence when present.\n- Relationships: lineage edges showing how one node derives from or produces another.\n- If nodes lack direct edges but share an upstream intent supplied as common parent #p, synthesize what that intent discovered. The common parent is context, not a member to compact.\nWrite the body as follows:\n1. Synthesize rather than enumerate. Follow causal relationships: which fact motivated an intent and which intent produced a conclusion. Do not copy every summary.\n2. Preserve distinctions between different conclusions instead of merging them into a vague sentence.\n3. Preserve evidence strength with observed/inferred labels. Inferred negative/uncertain conclusions remain tentative and open to verification, never definitive.\n4. Cite source node IDs after each conclusion, such as (#12,#28), so the planner can retrieve originals.\n5. State only what the input supports; introduce no invented information or judgments.\n6. Adapt length to the number of distinct conclusions, while remaining substantially shorter than all input summaries combined.\nOutput only the body.", "서로 관련된 탐색 노드를 통합 결론(body)으로 압축해 계획자가 이 영역에서 확인된 내용을 빠르게 이해하도록 하세요.\n입력은 연결된 하위 그래프입니다.\n- 노드: id, type, state, 가능한 confidence가 있는 의도/사실 한 문장 요약.\n- 관계: 노드 간 파생/산출을 보여주는 계보 연결.\n- 직접 연결이 없어도 공통 상위 의도 #p가 제공되면 그 의도가 알아낸 내용을 종합하세요. 공통 부모는 문맥이며 압축할 구성원이 아닙니다.\nbody 작성 규칙:\n1. 나열 대신 종합하세요. 어느 사실이 의도를 만들고 어느 의도가 결론을 냈는지 인과관계를 설명하고 요약을 하나씩 복사하지 마세요.\n2. 서로 다른 결론의 차이를 유지하고 모호한 한 문장으로 합치지 마세요.\n3. observed/inferred로 증거 강도를 유지하세요. 추론된 부정적/불확실한 결론은 잠정적이고 재검증 가능하며 확정 결론이 아닙니다.\n4. 각 결론 뒤에 (#12,#28)처럼 원본 노드 ID를 표시해 다시 조회할 수 있게 하세요.\n5. 입력에 근거한 내용만 쓰고 정보나 판단을 지어내지 마세요.\n6. 독립 결론 수에 맞춰 길이를 조정하되 전체 입력 요약의 합보다 충분히 짧게 하세요.\nbody 본문만 출력하세요.")
	Register("[llm-test] %s / %s @ %s — no HTTP request sent (configuration or connection failed)", "[llm-test] %s / %s @ %s — no HTTP request sent (configuration or connection failed)", "[llm-test] %s / %s @ %s — HTTP 요청을 보내지 못했습니다(설정 또는 연결 실패)")
	Register("[llm-test] %s / %s @ %s — attempt %d/%d HTTP %d\nResponse body: %s", "[llm-test] %s / %s @ %s — attempt %d/%d HTTP %d\nResponse body: %s", "[llm-test] %s / %s @ %s — 시도 %d/%d HTTP %d\n응답 본문: %s")
	Register("(empty)", "(empty)", "(비어 있음)")
	Register("…(truncated, %d bytes total)", "…(truncated, %d bytes total)", "…(잘림, 총 %d바이트)")
	Register("This is a connection test. Output exactly the two characters OK, with no reasoning, explanation, or other content.", "This is a connection test. Output exactly the two characters OK, with no reasoning, explanation, or other content.", "연결 테스트입니다. 추론, 설명 또는 다른 내용 없이 두 문자 OK만 출력하세요.")
	Register("Model returned no content (request succeeded, but no text was returned)", "Model returned no content (request succeeded, but no text was returned)", "모델 응답 내용 없음(요청은 성공했지만 텍스트가 반환되지 않음)")
}
